        @JacksonXmlProperty(isAttribute = true)
        @JsonProperty(value = "value", namespace = "uri:ns1")
        public int valueDefault = 42;
    }

    static class POJOXmlNsOverridesJsonNs {
        @JacksonXmlProperty(isAttribute = true, namespace = "uri:xml")
        @JsonProperty(value = "value2", namespace = "uri:json")
