    public void testFindNamespaceFallsBackToJsonPropertyWhenXmlNamespaceEmpty() {
        XmlMapper mapper = new XmlMapper();
        // ensure standard property discovery
        mapper.configure(MapperFeature.AUTO_DETECT_FIELDS, true);

