package com.fasterxml.jackson.dataformat.xml.ser;

import com.fasterxml.jackson.annotation.JsonRawValue;
import com.fasterxml.jackson.core.JsonGenerator;
import com.fasterxml.jackson.databind.JsonSerializer;
import com.fasterxml.jackson.databind.SerializerProvider;
import com.fasterxml.jackson.databind.annotation.JsonSerialize;
import com.fasterxml.jackson.dataformat.xml.XmlMapper;
import com.fasterxml.jackson.dataformat.xml.annotation.JacksonXmlProperty;
import com.fasterxml.jackson.dataformat.xml.annotation.JacksonXmlRootElement;
import com.fasterxml.jackson.dataformat.xml.annotation.JacksonXmlText;
import org.junit.Assert;
import org.junit.Test;

import java.io.IOException;

public class IssueRawValueUnwrappedWithTextTest {

    private static final String RAW_XML = "<a>A</a><b someAttribute=\"B\">B</b>";
    private static final String EXPECTED = "<test-pojo id=\"123\">" + RAW_XML + "</test-pojo>";

    @JacksonXmlRootElement(localName = "test-pojo")
    static class PojoWithJsonRawText {
        @JacksonXmlProperty(isAttribute = true)
        public String id;

        @JacksonXmlText
        @JsonRawValue
        public String value;

        public PojoWithJsonRawText() { }
        public PojoWithJsonRawText(String id, String value) {
            this.id = id;
            this.value = value;
        }
    }

    @JacksonXmlRootElement(localName = "test-pojo")
    static class PojoWithSubstringRawText {
        @JacksonXmlProperty(isAttribute = true)
        public String id;

        @JacksonXmlText
        @JsonSerialize(using = SubstringRawSerializer.class)
        public String value;

        public PojoWithSubstringRawText() { }
        public PojoWithSubstringRawText(String id, String value) {
            this.id = id;
            this.value = value;
        }
    }

    @JacksonXmlRootElement(localName = "test-pojo")
    static class PojoWithCharArrayRawText {
        @JacksonXmlProperty(isAttribute = true)
        public String id;

        @JacksonXmlText
        @JsonSerialize(using = CharArrayRawSerializer.class)
        public String value;

        public PojoWithCharArrayRawText() { }
        public PojoWithCharArrayRawText(String id, String value) {
            this.id = id;
            this.value = value;
        }
    }

    static class SubstringRawSerializer extends JsonSerializer<String> {
        @Override
        public void serialize(String value, JsonGenerator gen, SerializerProvider serializers) throws IOException {
            // expecting "xx" + RAW_XML + "yy"
            Assert.assertTrue("Test setup requires prefix and suffix 'xx'/'yy'", value.startsWith("xx") && value.endsWith("yy"));
            gen.writeRawValue(value, 2, value.length() - 4);
        }
    }

    static class CharArrayRawSerializer extends JsonSerializer<String> {
        @Override
        public void serialize(String value, JsonGenerator gen, SerializerProvider serializers) throws IOException {
            // expecting "xx" + RAW_XML + "yy"
            Assert.assertTrue("Test setup requires prefix and suffix 'xx'/'yy'", value.startsWith("xx") && value.endsWith("yy"));
            char[] ch = value.toCharArray();
            gen.writeRawValue(ch, 2, ch.length - 4);
        }
    }

    @Test
    public void testJsonRawValueWithJacksonXmlText_UnwrappedStringOverload() throws Exception {
        XmlMapper mapper = new XmlMapper();
        PojoWithJsonRawText pojo = new PojoWithJsonRawText("123", RAW_XML);

        String xml = mapper.writeValueAsString(pojo);

        Assert.assertEquals(EXPECTED, xml);
        Assert.assertFalse("No wrapper element should be emitted around raw text", xml.contains("<value>"));
    }

    @Test
    public void testJacksonXmlText_UnwrappedSubstringOverload() throws Exception {
        XmlMapper mapper = new XmlMapper();
        // value is wrapped with "xx" and "yy", serializer will write only the middle RAW_XML via writeRawValue(text, off, len)
        PojoWithSubstringRawText pojo = new PojoWithSubstringRawText("123", "xx" + RAW_XML + "yy");

