                                                    JavaType type) {
            return new FixedValueWriter(propDef, declaringClass.getAnnotations(), type);
        }
    }

    // POJO with a normal property and a virtual appended property "virtual"
    @JsonAppend(props = {
            @JsonAppend.Prop(name = "virtual", value = FixedValueWriter.class)
    })
    static class Pojo {
        public String name;

        public Pojo() { }
        public Pojo(String name) { this.name = name; }
    }

    @Test
    public void xmlMapperShouldSerializeJsonAppendVirtualOnce() throws Exception {
        XmlMapper mapper = new XmlMapper();
        // Ensure deterministic property order (default is fine, but keep behavior stable)
        mapper.enable(MapperFeature.SORT_PROPERTIES_ALPHABETICALLY);
        // Sorting may affect order of name/virtual; the key is uniqueness

        String xml = mapper.writeValueAsString(new Pojo("foo"));

