        Assert.assertTrue("XML should contain 'name' element", xml.contains("<name>foo</name>"));
        Assert.assertTrue("XML should end with root element", xml.endsWith("</Pojo>"));

        // The critical assertion: virtual property should be included exactly once
        Assert.assertEquals("Virtual property should be serialized exactly once",
                1, countOccurrences(xml, "<virtual>bar</virtual>"));

        // Optional ordering check: just ensure both are present and not duplicated
        int nameIndex = xml.indexOf("<name>foo</name>");
        int virtualIndex = xml.indexOf("<virtual>bar</virtual>");
        Assert.assertTrue("Expected both 'name' and 'virtual' elements present",
                nameIndex >= 0 && virtualIndex >= 0);
    }

