        Assert.assertEquals("Virtual property should be serialized exactly once in JSON",
                1, countOccurrences(json, "\"virtual\":\"bar\""));
    }

    private static int countOccurrences(String str, String sub) {
        int count = 0, idx = 0;
        while ((idx = str.indexOf(sub, idx)) != -1) {
            count++;
            idx += sub.length();
        }
        return count;
    }
}

